// Package web embeds the public static files (CSS, JS, fonts, images,
// favicons) so the server binary is self-contained. internal/assets serves
// them under content-hashed names.
//
// web/static/css/site.css is generated by Tailwind and gitignored: build the
// CSS before `go build` (the Dockerfile and `mage build` both do) or the
// stylesheet won't be in the binary.
package web

import "embed"

//go:embed static
var Static embed.FS
